//! Draws generated by resolving Standard leaves, staged for draw
//! replacements in Eternal builds: Kaito, Bane of Nightmares' conditional
//! draw, Braided Quipu's counted draw before its library move, Shanna,
//! Purifying Blade's paid draw, and Ertai Resurrected's draw for its
//! countered or destroyed target's controller.
//!
//! When the drawer may face a Dredge, Jace or Hullbreacher, or Miracle choice
//! (the condition under which the generated draw records its entry), the leaf
//! finishes everything before its draw, records the drawer and count, and
//! stages the draw as a resumable frame above its follow-up. Otherwise it
//! keeps its atomic executor, so other games are unchanged.
use super::*;
use crate::eternal_cards_v1::owned_draws_v1::{self, JournalV1};
use crate::event::CommittedEvent;
use crate::standard_cards_v1::StandardOpV1;
use crate::standard_legends_v1::{self as legends, LegendEffectV1};

/// Whether `op` is one of these drawing leaves.
pub(crate) fn draws(op: &EffectOp) -> bool {
    matches!(
        op,
        EffectOp::StandardV1(
            StandardOpV1::DrawIfOpponentLostLifeThisTurn
                | StandardOpV1::DrawPerArtifactThenSourceThirdFromTop
        ) | EffectOp::StandardLegendV1(
            LegendEffectV1::CounterStackTargetAndDraw
                | LegendEffectV1::DestroyTargetAndDraw
                | LegendEffectV1::ShannaPayAndDraw
        )
    )
}

/// The same condition `staged::enter_generated` uses to record the entry.
fn stages(state: &GameState, drawer: PlayerId) -> bool {
    cfg!(feature = "eternal-fixtures")
        && (crate::eternal_vintage_e7b_v1::dredge::may_need_draw_choice(state, drawer)
            || crate::eternal_legacy_e5b_v1::next_draw_may_offer_miracle(state, drawer))
}

fn framed(ctx: &ExecCtx, drawer: PlayerId) -> PlayerRef {
    if drawer == ctx.controller {
        PlayerRef::Controller
    } else {
        PlayerRef::Opponent
    }
}

/// The drawer and count this leaf recorded before `end`.
fn receipt(state: &GameState, ctx: &ExecCtx, path: &[u16], end: usize) -> Option<(PlayerId, u32)> {
    let item = ctx.stack_item_id?;
    state
        .engine
        .event_history
        .of_kinds_v2(&[EventKindV1::EternalOwnedDrawV1])
        .take_while(|(at, _)| *at < end)
        .filter_map(|(_, row)| {
            let CommittedEvent::EternalOwnedDrawV1 { journal } = row else {
                return None;
            };
            match journal.as_ref() {
                JournalV1::StandardStagedDrawV1 {
                    item: owner,
                    path: site,
                    drawer,
                    count,
                } if *owner == item && site == path => Some((*drawer, *count)),
                _ => None,
            }
        })
        .last()
}

fn follow_up(leaf: &EffectOp, path: &[u16]) -> Vec<EffectFrame> {
    match leaf {
        // Quipu's library move waits below its draw, at its own path.
        EffectOp::StandardV1(StandardOpV1::DrawPerArtifactThenSourceThirdFromTop) => {
            vec![EffectFrame::Program {
                op: leaf.clone(),
                path: path.to_vec(),
            }]
        }
        _ => Vec::new(),
    }
}

/// Records the fixed drawer and count, then stages the draw above the leaf's
/// follow-up. `false` when no replacement or Miracle choice can arise; the
/// caller then draws atomically.
fn stage(
    state: &mut GameState,
    continuation: &mut EffectContinuation,
    leaf: &EffectOp,
    path: &[u16],
    drawer: PlayerId,
    count: u32,
) -> bool {
    if count == 0 || !stages(state, drawer) {
        return false;
    }
    owned_draws_v1::record(
        state,
        JournalV1::StandardStagedDrawV1 {
            item: continuation.resolving_item.v4.stack_item_id,
            path: path.to_vec(),
            drawer,
            count,
        },
    );
    owned_draws_v1::staged::enter_generated(state, continuation, path, drawer);
    continuation.frames.extend(follow_up(leaf, path));
    continuation.frames.push(EffectFrame::Program {
        op: EffectOp::DrawCards {
            player: framed(&continuation.ctx, drawer),
            count,
        },
        path: path.to_vec(),
    });
    true
}

/// Runs one of these leaves in the resumable interpreter when its draw may
/// need a choice. `Ok(false)` leaves the leaf to its atomic executor.
pub(super) fn drive(
    state: &mut GameState,
    continuation: &mut EffectContinuation,
    leaf: &EffectOp,
    path: &[u16],
) -> Result<bool, String> {
    if !cfg!(feature = "eternal-fixtures") {
        return Ok(false);
    }
    let ctx = continuation.ctx.clone();
    match leaf {
        EffectOp::StandardV1(StandardOpV1::DrawIfOpponentLostLifeThisTurn) => Ok(
            crate::standard_cards_v1::opponent_lost_life_this_turn(state, &ctx)
                && stage(state, continuation, leaf, path, ctx.controller, 1),
        ),
        EffectOp::StandardV1(StandardOpV1::DrawPerArtifactThenSourceThirdFromTop) => {
            if receipt(state, &ctx, path, state.engine.event_history.len()).is_some() {
                // The follow-up, after the staged draw finished.
                crate::standard_cards_v1::put_source_third_from_top(&ctx, state);
                return Ok(true);
            }
            let count = crate::standard_cards_v1::controlled_artifact_count(state, ctx.controller);
            Ok(stage(
                state,
                continuation,
                leaf,
                path,
                ctx.controller,
                count,
            ))
        }
        EffectOp::StandardLegendV1(LegendEffectV1::CounterStackTargetAndDraw) => {
            if !legends::counter_target_controller(&ctx, state)
                .is_some_and(|drawer| stages(state, drawer))
            {
                return Ok(false);
            }
            // The drawer was saved before the target left the stack.
            if let Some(drawer) = legends::counter_stack_target(&ctx, state) {
                if state.engine.halted.is_none()
                    && !stage(state, continuation, leaf, path, drawer, 1)
                {
                    event::propose_and_commit(state, event::ProposedEvent::draw(drawer));
                }
            }
            Ok(true)
        }
        EffectOp::StandardLegendV1(LegendEffectV1::DestroyTargetAndDraw) => {
            if !legends::destroy_target_controller(&ctx, state)
                .is_some_and(|drawer| stages(state, drawer))
            {
                return Ok(false);
            }
            // The drawer was saved before the target was destroyed.
            if let Some(drawer) = legends::destroy_target(&ctx, state) {
                if state.engine.halted.is_none()
                    && !stage(state, continuation, leaf, path, drawer, 1)
                {
                    event::propose_and_commit(state, event::ProposedEvent::draw(drawer));
                }
            }
            Ok(true)
        }
        _ => Ok(false),
    }
}

/// Shanna's draw after its payment completed. `false` when the caller draws
/// atomically.
pub(super) fn stage_paid_draw(
    state: &mut GameState,
    continuation: &mut EffectContinuation,
    amount: u16,
    path: &[u16],
) -> bool {
    let leaf = EffectOp::StandardLegendV1(LegendEffectV1::ShannaPayAndDraw);
    let drawer = continuation.ctx.controller;
    stage(state, continuation, &leaf, path, drawer, u32::from(amount))
}

/// The draw one of these leaves staged at `path`: the recorded drawer and
/// count, checked against what the leaf can generate, and its follow-up.
pub(super) fn leaf_draw(
    leaf: &EffectOp,
    path: &[u16],
    ctx: &ExecCtx,
    state: &GameState,
    start: usize,
) -> Option<(PlayerRef, u32, Vec<EffectFrame>)> {
    if !cfg!(feature = "eternal-fixtures") || !draws(leaf) {
        return None;
    }
    let (drawer, count) = receipt(state, ctx, path, start)?;
    let controller = drawer == ctx.controller;
    let generated = match leaf {
        EffectOp::StandardV1(StandardOpV1::DrawIfOpponentLostLifeThisTurn) => {
            controller
                && count == 1
                && crate::standard_cards_v1::opponent_lost_life_this_turn(state, ctx)
        }
        EffectOp::StandardV1(StandardOpV1::DrawPerArtifactThenSourceThirdFromTop) => {
            controller && count > 0
        }
        EffectOp::StandardLegendV1(LegendEffectV1::ShannaPayAndDraw) => {
            controller
                && count > 0
                && count <= crate::standard_cards_v1::life_gained_this_turn(state, drawer)
        }
        EffectOp::StandardLegendV1(LegendEffectV1::CounterStackTargetAndDraw) => {
            count == 1
                && matches!(
                    ctx.target_contracts.first(),
                    Some(crate::state::StackTargetContractV4::StackItem { controller, .. })
                        if *controller == drawer
                )
        }
        EffectOp::StandardLegendV1(LegendEffectV1::DestroyTargetAndDraw) => {
            count == 1 && destroyed_target_controlled_by(state, ctx, drawer, start)
        }
        _ => false,
    };
    generated.then(|| (framed(ctx, drawer), count, follow_up(leaf, path)))
}

/// The destroyed target's last battlefield controller, or its controller now
/// if it survived the destruction.
fn destroyed_target_controlled_by(
    state: &GameState,
    ctx: &ExecCtx,
    drawer: PlayerId,
    end: usize,
) -> bool {
    let Some(crate::state::StackTargetContractV4::Object {
        object,
        zone_change_count,
        ..
    }) = ctx.target_contracts.first().copied()
    else {
        return false;
    };
    let Some(live) = state.objects.try_get(object) else {
        return false;
    };
    if live.zone == Zone::Battlefield && live.zone_change_count == zone_change_count {
        return live.controller == drawer;
    }
    let Some(history) = state.engine.event_history.get(..end) else {
        return false;
    };
    history.iter().rev().any(|row| {
        matches!(row, CommittedEvent::ZoneChange {
            object: departed,
            from: Zone::Battlefield,
            controller_before,
            ..
        } if *departed == object && *controller_before == drawer)
    })
}
